 "content": "from collections import Counter


def transform(grid):
    """Compress each 3x3 block to its non-background marker color.

    The background is the two-color field 0/5; marker colors are 1-4, 6-9.
    """
    h, w = len(grid), len(grid[0])
    out = []
    for br in range(0, h, 3):
        row = []
        for bc in range(0, w, 3):
            colors = [grid[r][c]
                      for r in range(br, min(br + 3, h))
                      for c in range(bc, min(bc + 3, w))
                      if grid[r][c] not in (0, 5)]
            if colors:
                counts = Counter(colors)
                # A block represents its marker; ties use the first encountered.
                color = max(dict.fromkeys(colors), key=lambda x: counts[x])
                row.append(color)
            else:
                row.append(0)
        out.append(row)
    return out
